namespace UniversityCourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public required string Code { get; set; }
    public required string Title { get; set; }
    public required string Description { get; set; }
    public int Credits { get; set; }
    public required string Instructor { get; set; }
    public required string InstructorBio { get; set; }
    public required string Schedule { get; set; }
    public required string Department { get; set; }
    public bool IsFeatured { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Full name is required.")]
    [StringLength(100, ErrorMessage = "Name cannot exceed 100 characters.")]
    public string Name { get; set; } = "";

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Za-z0-9\-]+$", ErrorMessage = "Student ID must contain only letters, numbers, and hyphens.")]
    public string StudentId { get; set; } = "";

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CourseCatalogService
{
    private readonly List<Course> _courses =
    [
        new()
        {
            Id = 1, Code = "CS 101", Title = "Introduction to Computer Science",
            Description = "A broad introduction to computer science covering computational thinking, basic algorithms, data representation, and an overview of modern computing systems. No prior programming experience required.",
            Credits = 3, Instructor = "Dr. Alice Chen", Schedule = "Mon/Wed 9:00–10:15 AM",
            Department = "Computer Science", IsFeatured = true,
            InstructorBio = "Dr. Alice Chen holds a Ph.D. from MIT and has over 15 years of experience teaching introductory CS courses. Her research focuses on CS education and making computing accessible to all students."
        },
        new()
        {
            Id = 2, Code = "CS 201", Title = "Data Structures and Algorithms",
            Description = "Study of fundamental data structures (arrays, linked lists, trees, graphs, hash tables) and algorithm design techniques (divide and conquer, dynamic programming, greedy algorithms). Emphasis on analysis of time and space complexity.",
            Credits = 4, Instructor = "Dr. Bob Martinez", Schedule = "Tue/Thu 11:00 AM–12:15 PM",
            Department = "Computer Science", IsFeatured = false,
            InstructorBio = "Dr. Bob Martinez is an ACM Distinguished Educator whose work on algorithm visualization tools has been adopted by universities worldwide."
        },
        new()
        {
            Id = 3, Code = "CS 350", Title = "Machine Learning Fundamentals",
            Description = "Introduction to machine learning concepts including supervised and unsupervised learning, neural networks, decision trees, and model evaluation. Students complete hands-on projects using Python and scikit-learn.",
            Credits = 3, Instructor = "Dr. Alice Chen", Schedule = "Mon/Wed/Fri 1:00–1:50 PM",
            Department = "Computer Science", IsFeatured = true,
            InstructorBio = "Dr. Alice Chen holds a Ph.D. from MIT and has over 15 years of experience teaching introductory CS courses. Her research focuses on CS education and making computing accessible to all students."
        },
        new()
        {
            Id = 4, Code = "MATH 101", Title = "Calculus I",
            Description = "Limits, continuity, derivatives, and integrals of single-variable functions. Applications to rates of change, optimization, and area under curves.",
            Credits = 4, Instructor = "Prof. Carol Nguyen", Schedule = "Mon/Wed/Fri 10:00–10:50 AM",
            Department = "Mathematics", IsFeatured = true,
            InstructorBio = "Prof. Carol Nguyen is an award-winning mathematics educator with a passion for helping students overcome math anxiety. She has published extensively on pedagogical approaches to calculus instruction."
        },
        new()
        {
            Id = 5, Code = "MATH 201", Title = "Linear Algebra",
            Description = "Vector spaces, linear transformations, matrices, determinants, eigenvalues, and eigenvectors. Applications to systems of equations and geometry.",
            Credits = 3, Instructor = "Prof. Carol Nguyen", Schedule = "Tue/Thu 2:00–3:15 PM",
            Department = "Mathematics", IsFeatured = false,
            InstructorBio = "Prof. Carol Nguyen is an award-winning mathematics educator with a passion for helping students overcome math anxiety. She has published extensively on pedagogical approaches to calculus instruction."
        },
        new()
        {
            Id = 6, Code = "MATH 310", Title = "Probability and Statistics",
            Description = "Probability theory, random variables, distributions, hypothesis testing, confidence intervals, and regression analysis. Applications to data science and experimental design.",
            Credits = 3, Instructor = "Dr. David Park", Schedule = "Mon/Wed 3:00–4:15 PM",
            Department = "Mathematics", IsFeatured = false,
            InstructorBio = "Dr. David Park brings industry experience from his years as a data scientist at a Fortune 500 company before joining academia. He bridges the gap between theoretical statistics and real-world applications."
        },
        new()
        {
            Id = 7, Code = "PHYS 101", Title = "General Physics I",
            Description = "Mechanics, thermodynamics, and waves. Covers Newton's laws, energy, momentum, rotational motion, and oscillations with laboratory component.",
            Credits = 4, Instructor = "Dr. Elena Rossi", Schedule = "Tue/Thu 9:00–10:15 AM, Lab: Fri 2:00–4:50 PM",
            Department = "Physics", IsFeatured = false,
            InstructorBio = "Dr. Elena Rossi is a former CERN researcher who brings cutting-edge physics insights to the classroom. She is known for her engaging demonstrations and inquiry-based lab design."
        },
        new()
        {
            Id = 8, Code = "PHYS 220", Title = "Electromagnetism",
            Description = "Electric fields, magnetic fields, Maxwell's equations, electromagnetic waves, and optics. Includes laboratory experiments and computational modeling.",
            Credits = 4, Instructor = "Dr. Elena Rossi", Schedule = "Mon/Wed 11:00 AM–12:15 PM, Lab: Thu 2:00–4:50 PM",
            Department = "Physics", IsFeatured = true,
            InstructorBio = "Dr. Elena Rossi is a former CERN researcher who brings cutting-edge physics insights to the classroom. She is known for her engaging demonstrations and inquiry-based lab design."
        },
        new()
        {
            Id = 9, Code = "ENG 101", Title = "Composition and Rhetoric",
            Description = "Develops skills in academic writing, critical reading, argumentation, and research methodology. Students produce essays across multiple genres and complete a research project.",
            Credits = 3, Instructor = "Prof. Frank Liu", Schedule = "Mon/Wed/Fri 9:00–9:50 AM",
            Department = "English", IsFeatured = false,
            InstructorBio = "Prof. Frank Liu is a published author and composition scholar whose creative nonfiction has appeared in national literary journals. He emphasizes writing as a tool for critical thinking."
        },
        new()
        {
            Id = 10, Code = "ENG 250", Title = "American Literature Survey",
            Description = "A survey of American literature from the colonial period to the present, exploring major authors, movements, and themes in the context of American history and culture.",
            Credits = 3, Instructor = "Dr. Grace Thompson", Schedule = "Tue/Thu 1:00–2:15 PM",
            Department = "English", IsFeatured = false,
            InstructorBio = "Dr. Grace Thompson specializes in 20th-century American fiction and has published two books on the intersection of literature and social justice movements."
        },
        new()
        {
            Id = 11, Code = "HIST 101", Title = "World History to 1500",
            Description = "Survey of world civilizations from prehistory through the late medieval period, covering the development of agriculture, cities, empires, trade networks, and religious traditions.",
            Credits = 3, Instructor = "Dr. Hannah Kim", Schedule = "Tue/Thu 11:00 AM–12:15 PM",
            Department = "History", IsFeatured = false,
            InstructorBio = "Dr. Hannah Kim is an archaeologist and historian whose fieldwork in East Asia has reshaped understanding of ancient trade routes. She brings artifacts and primary sources into every lecture."
        },
        new()
        {
            Id = 12, Code = "HIST 205", Title = "Modern European History",
            Description = "Europe from the Enlightenment to the present day: revolutions, industrialization, nationalism, world wars, the Cold War, and European integration.",
            Credits = 3, Instructor = "Prof. Ian Wallace", Schedule = "Mon/Wed 2:00–3:15 PM",
            Department = "History", IsFeatured = true,
            InstructorBio = "Prof. Ian Wallace is a Fulbright Scholar and author of three books on European political history. His lectures draw on extensive archival research conducted across six countries."
        },
    ];

    public IReadOnlyList<string> GetDepartments()
    {
        return _courses
            .Select(c => c.Department)
            .Distinct()
            .OrderBy(d => d)
            .ToList();
    }

    public IReadOnlyList<Course> SearchCourses(string? searchTerm, string? department)
    {
        var query = _courses.AsEnumerable();

        if (!string.IsNullOrWhiteSpace(department))
        {
            query = query.Where(c => c.Department.Equals(department, StringComparison.OrdinalIgnoreCase));
        }

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Instructor.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.OrderBy(c => c.Department).ThenBy(c => c.Code).ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public IReadOnlyList<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public IReadOnlyList<Course> GetAllCourses() => _courses;

    public bool SubmitEnrollmentRequest(EnrollmentRequest request)
    {
        // In a real application, this would persist to a database.
        var course = GetCourse(request.CourseId);
        return course is not null;
    }
}

